# ── Ground and heights along the wall ───────────────────────────────────────────────────────────────────────
def smooth(a, k):
    p = np.pad(a, k, mode="edge")
    return np.convolve(p, np.ones(2 * k + 1) / (2 * k + 1), mode="valid")


def runmin(a, k):
    p = np.pad(a, k, mode="edge")
    return np.array([p[i:i + 2 * k + 1].min() for i in range(len(a))])


PROF = np.array(DATA["profile"], float)
PX = PROF[:, :2]
PS = np.r_[0, np.cumsum(np.linalg.norm(np.diff(PX, axis=0), axis=1))]
G_IN, G_W, G_OUT = smooth(PROF[:, 2], 2), smooth(PROF[:, 3], 2), smooth(PROF[:, 4], 2)
WALK = smooth(np.maximum(G_OUT + WALK_ABOVE, G_IN + 1.8), 2)
BOT = runmin(np.minimum(np.minimum(PROF[:, 2], PROF[:, 3]), PROF[:, 4]), 2) - FOUND


def s_of(P):
    """Arc length along the inner face of the nearest point of the profile line."""
    P = np.asarray(P, float).reshape(-1, 2)[:, None, :]
    A, B = PX[:-1][None], PX[1:][None]
    AB = B - A
    t = np.clip(((P - A) * AB).sum(-1) / (AB * AB).sum(-1), 0, 1)
    d = ((P - (A + AB * t[..., None])) ** 2).sum(-1)
    k = d.argmin(1)
    return PS[k] + t[np.arange(len(k)), k] * (PS[k + 1] - PS[k])


def at(P, arr):
    return np.interp(s_of(P), PS, arr)


# ── Geometry helpers ────────────────────────────────────────────────────────────────────────────────────────
def seg_dist(p, L):
    a, b = L[:-1], L[1:]
    ab = b - a
    t = np.clip(((p - a) * ab).sum(1) / np.maximum((ab * ab).sum(1), 1e-12), 0, 1)
    q = a + ab * t[:, None]
    return np.linalg.norm(p - q, axis=1).min()


def seg_normals(L, toward=None, away=None):
    """Unit normals of the segments of an open polyline, all on the same side: the side of `toward` (a point),
    or the side away from `away`."""
    t = np.diff(L, axis=0)
    t /= np.maximum(np.linalg.norm(t, axis=1, keepdims=True), 1e-12)
    n = np.stack([t[:, 1], -t[:, 0]], 1)
    mid = (L[:-1] + L[1:]) / 2
    ref = (toward - mid) if toward is not None else (mid - away)
    w = np.linalg.norm(L[1:] - L[:-1], axis=1)
    if ((n * ref).sum(1) * w).sum() < 0:
        n = -n
    return n


def offset_open(L, n, d, limit=0.35):
    """Offset an open polyline by d along its segment normals n (mitred joints)."""
    out = []
    for i in range(len(L)):
        if i == 0:
            m, k = n[0], 1.0
        elif i == len(L) - 1:
            m, k = n[-1], 1.0
        else:
            m = n[i - 1] + n[i]
            lm = np.linalg.norm(m)
            if lm < 1e-6:
                m, k = n[i], 1.0
            else:
                m = m / lm
                k = 1.0 / max(float(np.dot(m, n[i])), limit)
        out.append(L[i] + m * d * k)
    return np.array(out)


def resample(L, flags, maxlen):
    """Split segments longer than maxlen; flags (one per segment) are carried to the pieces."""
    P, F = [L[0]], []
    for i in range(len(L) - 1):
        a, b = L[i], L[i + 1]
        k = max(1, int(math.ceil(np.linalg.norm(b - a) / maxlen)))
        for j in range(1, k + 1):
            P.append(a + (b - a) * j / k)
            F.append(flags[i])
    return np.array(P), np.array(F, bool)


class Builder:
    """Collects polygons with their own vertices (sharp edges), each oriented towards a given normal."""

    def __init__(self):
        self.v, self.f, self.c = [], [], []
        self.n = 0

    def poly(self, pts, col, nrm):
        pts = np.asarray(pts, float)
        nw = np.zeros(3)
        for i in range(len(pts)):
            a, b = pts[i], pts[(i + 1) % len(pts)]
            nw += np.cross(a, b)
        if np.dot(nw, nrm) < 0:
            pts = pts[::-1]
        o = self.n
        self.v.append(pts)
        self.c.append(np.tile(np.asarray(col, float), (len(pts), 1)))
        self.f.append(np.array([(o, o + i, o + i + 1) for i in range(1, len(pts) - 1)]))
        self.n += len(pts)

    def mesh(self, m=None):
        if m is not None and len(m.v):
            self.f.append(m.f + self.n)
            self.v.append(m.v); self.c.append(m.c)
            self.n += len(m.v)
        return Mesh(np.vstack(self.v), np.vstack(self.f), np.vstack(self.c))


def strip(L, ybot, ytop, n, col, smooth_deg=32.0):
    """Vertical faces along an open polyline L from ybot to ytop (arrays per vertex), facing the 2D normals n
    (one per segment). Vertices are shared across gentle bends (smooth shading), split at sharp corners."""
    L = np.asarray(L, float)
    v, f, sharp = [], [], [False]
    t = np.diff(L, axis=0)
    t /= np.maximum(np.linalg.norm(t, axis=1, keepdims=True), 1e-12)
    for i in range(1, len(L) - 1):
        sharp.append(float(np.dot(t[i - 1], t[i])) < math.cos(math.radians(smooth_deg)))
    sharp.append(False)
    idx_end = {}                                           # vertex index of (point i) for the segment that ends there
    for i in range(len(L) - 1):
        for j in (i, i + 1):
            if j == i and (i in idx_end) and not sharp[i]:
                continue
        # start vertices of this segment
        if i in idx_end and not sharp[i]:
            a0, a1 = idx_end[i]
        else:
            a0 = len(v); v.append((L[i][0], ybot[i], L[i][1])); a1 = len(v); v.append((L[i][0], ytop[i], L[i][1]))
        b0 = len(v); v.append((L[i + 1][0], ybot[i + 1], L[i + 1][1])); b1 = len(v); v.append((L[i + 1][0], ytop[i + 1], L[i + 1][1]))
        idx_end[i + 1] = (b0, b1)
        V = np.array(v)
        fn = np.cross(V[b0] - V[a0], V[b1] - V[a0])
        if fn[0] * n[i][0] + fn[2] * n[i][1] >= 0:
            f += [(a0, b0, b1), (a0, b1, a1)]
        else:
            f += [(a0, b1, b0), (a0, a1, b1)]
    return Mesh(v, f, col)


def ribbon(A, B, ya, yb, col):
    """Near-horizontal quads between two matching polylines (parapet tops), facing up."""
    v, f = [], []
    for i in range(len(A) - 1):
        o = len(v)
        P = [(A[i][0], ya[i], A[i][1]), (A[i + 1][0], ya[i + 1], A[i + 1][1]), (B[i + 1][0], yb[i + 1], B[i + 1][1]), (B[i][0], yb[i], B[i][1])]
        v += P
        fn = np.cross(np.subtract(P[1], P[0]), np.subtract(P[2], P[0]))
        f += [(o, o + 1, o + 2), (o, o + 2, o + 3)] if fn[1] >= 0 else [(o, o + 2, o + 1), (o, o + 3, o + 2)]
    return Mesh(v, f, col)


def flat_cap(poly, y, col):
    """A horizontal polygon (y scalar or a function of the points), facing up."""
    pts, tris = triangulate([tuple(p) for p in poly])
    ys = y(pts) if callable(y) else np.full(len(pts), float(y))
    V = np.stack([pts[:, 0], ys, pts[:, 1]], 1)
    a, b, c = V[tris[:, 0]], V[tris[:, 1]], V[tris[:, 2]]
    up = np.cross(b - a, c - a)[:, 1] >= 0
    tris = np.where(up[:, None], tris, tris[:, ::-1])
    return Mesh(V, tris, col)


def merlons(C, T, y0, y1, dep, col, w=MER_W, cap=MER_CAP):
    """Merlons (box + pyramidal cap) centred at C (n,2) along tangents T, from y0 to y1 (arrays), dep deep."""
    C, T = np.asarray(C, float), np.asarray(T, float)
    if not len(C):
        return Mesh()
    N = np.stack([T[:, 1], -T[:, 0]], 1)
    corners = [(-1, -1), (1, -1), (1, 1), (-1, 1)]
    Q = np.stack([C + T * (sx * w / 2) + N * (sz * dep / 2) for sx, sz in corners], 1)       # (n,4,2)
    V, F = [], []
    n = len(C)
    for k in range(4):
        p, q = Q[:, k], Q[:, (k + 1) % 4]
        quadv = np.stack([np.c_[p[:, 0], y0, p[:, 1]], np.c_[q[:, 0], y0, q[:, 1]],
                          np.c_[q[:, 0], y1, q[:, 1]], np.c_[p[:, 0], y1, p[:, 1]]], 1)
        V.append(quadv)
    apex = np.c_[C[:, 0], y1 + cap, C[:, 1]][:, None, :]
    for k in range(4):
        p, q = Q[:, k], Q[:, (k + 1) % 4]
        V.append(np.concatenate([np.c_[p[:, 0], y1, p[:, 1]][:, None], np.c_[q[:, 0], y1, q[:, 1]][:, None], apex], 1))
    # faces with local indices: 4 quads (16 verts) then 4 triangles (12 verts)
    allv = np.concatenate(V, 1)                                                                  # (n,28,3)
    loc = []
    for k in range(4):
        o = 4 * k
        loc += [(o, o + 1, o + 2), (o, o + 2, o + 3)]
    for k in range(4):
        o = 16 + 3 * k
        loc.append((o, o + 1, o + 2))
    loc = np.array(loc)
    ctr = np.c_[C[:, 0], (y0 + y1) / 2, C[:, 1]]
    a, b, c = allv[:, loc[:, 0]], allv[:, loc[:, 1]], allv[:, loc[:, 2]]
    fn = np.cross(b - a, c - a)
    outw = ((a + b + c) / 3 - ctr[:, None, :])
    flip = (fn * outw).sum(-1) < 0                                                               # (n,12)
    faces = np.broadcast_to(loc, (n, len(loc), 3)).copy()
    faces[flip] = faces[flip][:, ::-1]
    faces = faces + (np.arange(n) * 28)[:, None, None]
    cols = np.repeat(np.clip(np.asarray(col) * (1 + rng.normal(0, 0.035, (n, 1))), 0, 1), 28, 0)
    return Mesh(allv.reshape(-1, 3), faces.reshape(-1, 3), cols)


def place_along(L, keep, pitch=MER_PITCH, start=0.55):
    """Centres and tangents every `pitch` metres along the runs of segments of L where keep is True."""
    C, T = [], []
    i = 0
    while i < len(L) - 1:
        if not keep[i]:
            i += 1
            continue
        j = i
        while j < len(L) - 1 and keep[j]:
            j += 1
        R = L[i:j + 1]
        seg = np.linalg.norm(np.diff(R, axis=0), axis=1)
        s = np.r_[0, np.cumsum(seg)]
        if s[-1] > MER_W + 0.3:
            n = int((s[-1] - MER_W - 2 * 0.1) // pitch) + 1
            used = (n - 1) * pitch
            for k in range(n):
                sk = (s[-1] - used) / 2 + k * pitch
                m = min(np.searchsorted(s, sk, side="right") - 1, len(seg) - 1)
                u = (sk - s[m]) / max(seg[m], 1e-9)
                C.append(R[m] + (R[m + 1] - R[m]) * u)
                T.append((R[m + 1] - R[m]) / max(seg[m], 1e-9))
        i = j
    return np.array(C).reshape(-1, 2), np.array(T).reshape(-1, 2)


def arch_profile(w, ys, y0, seg=10):
    """A gate opening seen from the front: (u, y) from the ground y0, straight jambs to ys, semicircular head."""
    P = [(-w / 2, y0), (w / 2, y0)]
    for k in range(seg + 1):
        a = math.pi * k / seg
        P.append((w / 2 * math.cos(a), ys + w / 2 * math.sin(a)))
    return P


def PROF_CCW(P):
    """Signed area of a 2D profile (> 0 counter-clockwise)."""
    return ring_area(P)


# ── Towers ──────────────────────────────────────────────────────────────────────────────────────────────────
def find_towers():
    dO = np.array([seg_dist(p, I) for p in O])
    bump = dO > BUMP
    bump[836] = False                     # a corner of the wall north of the Peso de la Harina, not a tower
    groups, cur = [], None
    for i, b in enumerate(bump):
        if b and cur is None:
            cur = [i, i]
        elif b:
            cur[1] = i
        elif cur is not None:
            groups.append(cur); cur = None
    if cur:
        groups.append(cur)
    splits = {g["outer"]: name for name, g in GATES.items()}
    towers = []
    for a, b in groups:
        i0, i1 = a - 1, min(b + 1, len(O) - 1)
        cut = [k for k in splits if i0 < k <= i1 - 1]
        if not cut:
            spans = [(i0, i1)]
        elif cut[0] - 1 <= i0:            # the passage is at the foot of the tower
            spans = [(cut[0], i1)]
        else:
            spans = [(i0, cut[0] - 1), (cut[0], i1)]
        for j0, j1 in spans:
            towers.append({"i0": j0, "i1": j1, "gate": splits[cut[0]] if cut and splits[cut[0]] in GREAT else None,
                           "end": j1 == len(O) - 1})
    return towers


def chaikin(P, it=2):
    """Round the corners of an open polyline (the ends stay where they are)."""
    P = np.asarray(P, float)
    for _ in range(it):
        if len(P) < 3:
            return P
        Q = [P[0]]
        for i in range(len(P) - 1):
            a, b = P[i], P[i + 1]
            if i > 0:
                Q.append(0.75 * a + 0.25 * b)
            if i < len(P) - 2:
                Q.append(0.25 * a + 0.75 * b)
        Q.append(P[-1])
        P = np.array(Q)
    return P


def tower_poly(t):
    arc = chaikin(O[t["i0"]:t["i1"] + 1])                 # the OSM bump, its corners rounded (cubos are D-shaped)
    if t["end"]:                          # the tower at the north end of the cimorro: closed on the inner face
        return arc, np.vstack([arc, I[-1:]])
    a, b = arc[0], arc[-1]
    ch = b - a
    n = np.array([ch[1], -ch[0]]) / max(np.linalg.norm(ch), 1e-9)
    mid = (a + b) / 2
    if np.dot(n, arc.mean(0) - mid) > 0:  # point away from the bump (towards the town)
        n = -n
    return arc, np.vstack([arc, b + n * TOWER_BACK, a + n * TOWER_BACK])


def tower(t, parts, top_extra=None):
    arc, poly = tower_poly(t)
    ctr = poly.mean(0)
    walk = float(at(ctr[None], WALK)[0])
    a, b = arc[0], arc[-1]
    ch = (b - a) / max(np.linalg.norm(b - a), 1e-9)
    depth = max(abs(ch[0] * (p - a)[1] - ch[1] * (p - a)[0]) for p in arc)
    terrace = walk + (top_extra if top_extra is not None else (2.4 if depth > 6.0 else 1.2))
    bot = float(at(poly, BOT).min()) - 2.0
    ptop = terrace + PARAPET
    # outer walls along the arc (smooth), back walls (sharp) up to the terrace
    n_out = seg_normals(arc, away=ctr)
    parts["stone"].append(strip(arc, np.full(len(arc), bot), np.full(len(arc), ptop), n_out, GRANITE))
    back = np.vstack([arc[-1:], poly[len(arc):], arc[:1]])
    nb = seg_normals(back, away=ctr)
    parts["stone"].append(strip(back, np.full(len(back), bot), np.full(len(back), terrace), nb, GRANITE, smooth_deg=1))
    parts["walk"].append(flat_cap(poly, terrace, WALK_C))
    # parapet along the arc, its ends, merlons
    n_in = -n_out
    arc_in = offset_open(arc, n_in, PAR_T)
    parts["stone"].append(strip(arc_in, np.full(len(arc), terrace), np.full(len(arc), ptop), n_in, GRANITE))
    parts["stone"].append(ribbon(arc, arc_in, np.full(len(arc), ptop), np.full(len(arc), ptop), WALK_C))
    bld = Builder()
    for p, q, tt in ((arc[0], arc_in[0], arc[1] - arc[0]), (arc[-1], arc_in[-1], arc[-2] - arc[-1])):
        bld.poly([(p[0], terrace, p[1]), (q[0], terrace, q[1]), (q[0], ptop, q[1]), (p[0], ptop, p[1])], GRANITE,
                 (-tt[0], 0, -tt[1]))
    parts["stone"].append(bld.mesh())
    mid = (arc + arc_in) / 2
    C, T = place_along(mid, np.ones(len(mid) - 1, bool), pitch=1.55)
    if len(C):
        parts["merlon"].append(merlons(C, T, np.full(len(C), ptop - 0.12), np.full(len(C), ptop + MER_H), PAR_T + 0.06, GRANITE))
    # a thin string course of corbels under the parapet (the dark line seen on the photos)
    band = offset_open(arc, n_out, 0.14)
    yb0, yb1 = terrace - 0.55, terrace - 0.15
    parts["stone"].append(strip(band, np.full(len(arc), yb0), np.full(len(arc), yb1), n_out, GRANITE * 0.86))
    parts["stone"].append(ribbon(arc, band, np.full(len(arc), yb1), np.full(len(arc), yb1), GRANITE * 0.9))
    return {"arc": arc, "poly": poly, "terrace": terrace, "walk": walk, "ctr": ctr}


# ── The wall ────────────────────────────────────────────────────────────────────────────────────────────────
def wall(towers, parts):
    drop = set()
    chord_after = set()
    for t in towers:
        if t["end"]:
            drop.update(range(t["i0"] + 1, t["i1"] + 1))
        else:
            drop.update(range(t["i0"] + 1, t["i1"]))
            chord_after.add(t["i0"])
    keep_idx = [k for k in range(len(O)) if k not in drop]
    Ok = O[keep_idx]
    flags = np.array([keep_idx[j] not in chord_after for j in range(len(keep_idx) - 1)])   # True = real face
    Or, Fr = resample(Ok, flags, 6.0)
    Ir, _ = resample(I, np.ones(len(I) - 1, bool), 6.0)
    n_o = seg_normals(Or, away=np.zeros(2))              # outwards
    n_i = seg_normals(Ir, away=np.zeros(2))
    Oin = offset_open(Or, -n_o, PAR_T)
    wo, wi, wn = at(Or, WALK), at(Ir, WALK), at(Oin, WALK)
    bo, bi = at(Or, BOT), at(Ir, BOT)
    parts["stone"].append(strip(Ir, bi, wi, -n_i, GRANITE))                     # inner face
    parts["stone"].append(strip(Or, bo, wo + PARAPET, n_o, GRANITE))            # outer face
    parts["stone"].append(strip(Oin, wn, wn + PARAPET, -n_o, GRANITE))          # parapet, walk side
    parts["stone"].append(ribbon(Or, Oin, wo + PARAPET, wn + PARAPET, WALK_C))  # parapet top
    ring = [tuple(p) for p in Ir] + [tuple(p) for p in Oin[::-1]]
    parts["walk"].append(flat_cap(ring, lambda P: at(P, WALK), WALK_C))         # wall walk
    mid = (Or + Oin) / 2
    C, T = place_along(mid, Fr)
    if len(C):
        yt = at(C, WALK) + PARAPET
        parts["merlon"].append(merlons(C, T, yt - 0.12, yt + MER_H, PAR_T + 0.06, GRANITE))
    return Or, Oin, Ir


# ── Gates ───────────────────────────────────────────────────────────────────────────────────────────────────
def face_frame(L, k, v, avoid=None):
    """At vertex k of polyline L: the adjacent segment most across the passage direction v -> (unit u, segment)."""
    best = None
    for a, b in ((k - 1, k), (k, k + 1)):
        if a < 0 or b >= len(L) or (avoid is not None and (a, b) in avoid):
            continue
        u = L[b] - L[a]
        ln = np.linalg.norm(u)
        if ln < 1e-6:
            continue
        u = u / ln
        score = abs(np.dot(u, v))
        if best is None or score < best[0]:
            best = (score, u, (a, b), ln)
    return best


def gate_cap(bld, ctr, u, n, y0, ys, w, col=DARK):
    P = arch_profile(w, ys, y0)
    pts = [(ctr[0] + u[0] * pu + n[0] * 0.05, py, ctr[1] + u[1] * pu + n[1] * 0.05) for pu, py in P]
    bld.poly(pts, col, (n[0], 0, n[1]))


def gates(towers, parts):
    bld = Builder()
    base_pts = {t["i0"] for t in towers} | {t["i1"] for t in towers}
    for name, g in GATES.items():
        pi, po = I[g["inner"]], O[g["outer"]]
        v = (po - pi) / np.linalg.norm(po - pi)
        w = 4.2 if name in GREAT else 3.4
        s_mid = (pi + po) / 2
        y0 = float(at(s_mid[None], G_W)[0]) - 0.4
        walk = float(at(s_mid[None], WALK)[0])
        ys = min(y0 + 4.2, walk - 1.4 - w / 2)
        # outer face
        if name in GREAT:
            k = g["outer"]
            co, u = (O[k - 1] + O[k]) / 2, (O[k] - O[k - 1]) / np.linalg.norm(O[k] - O[k - 1])
        else:
            fb = face_frame(O, g["outer"], v)
            u, (a, b), ln = fb[1], fb[2], fb[3]
            co = po.copy()
            if g["outer"] in base_pts:                    # the passage starts at a tower: move the arch off it
                inward = 1 if a == g["outer"] else -1
                co = po + u * inward * min(w / 2 + 0.4, ln / 2)
        no = np.array([u[1], -u[0]])
        if np.dot(no, v) < 0:
            no = -no
        gate_cap(bld, co, u, no, y0, ys, w)
        # inner face
        fb = face_frame(I, g["inner"], v)
        ui = fb[1]
        ni = np.array([ui[1], -ui[0]])
        if np.dot(ni, -v) < 0:
            ni = -ni
        yi0 = float(at(pi[None], G_IN)[0]) - 0.4
        ysi = min(max(yi0 + 3.6, ys), float(at(pi[None], WALK)[0]) - 1.2 - w / 2)
        gate_cap(bld, pi, ui, ni, min(yi0, y0), ysi, w)
    parts["dark"].append(bld.mesh())


def great_gate(name, ta, tb, parts):
    """Two towers joined high up by an arch (Puerta del Alcázar, Puerta de San Vicente)."""
    A, B = ta["arc"][1:-1], tb["arc"][1:-1]
    pa = A[np.argmin(np.linalg.norm(A - tb["ctr"], axis=1))]
    pb = B[np.argmin(np.linalg.norm(B - ta["ctr"], axis=1))]
    span = float(np.linalg.norm(pb - pa))
    u = (pb - pa) / span
    n = np.array([u[1], -u[0]])
    if np.dot(n, (pa + pb) / 2) < 0:                     # outwards = away from the town centre
        n = -n
    walk = (ta["walk"] + tb["walk"]) / 2
    ysp = walk + 3.0
    r = span / 2
    ytop = ysp + r + 0.9
    dep = 2.4
    prof = [(-1.5, ysp), (0.0, ysp)]
    for k in range(1, 16):
        a = math.pi * k / 16
        prof.append((r - r * math.cos(a), ysp + r * math.sin(a)))
    prof += [(span, ysp), (span + 1.5, ysp), (span + 1.5, ytop), (-1.5, ytop)]
    pts, tris = triangulate(prof)
    ms = []
    for off, sgn in ((0.0, 1), (-dep, -1)):
        V = np.array([(pa[0] + u[0] * pu + n[0] * off, py, pa[1] + u[1] * pu + n[1] * off) for pu, py in pts])
        a, b, c = V[tris[:, 0]], V[tris[:, 1]], V[tris[:, 2]]
        fn = np.cross(b - a, c - a)
        ok = (fn[:, 0] * n[0] + fn[:, 2] * n[1]) * sgn >= 0
        ms.append(Mesh(V, np.where(ok[:, None], tris, tris[:, ::-1]), GRANITE))
    bld = Builder()
    for i in range(len(prof)):
        (u0, y0), (u1, y1) = prof[i], prof[(i + 1) % len(prof)]
        p0 = pa + u * u0; p1 = pa + u * u1
        # outward normal of this edge in the (u, y) plane (the profile is a simple polygon: use its orientation)
        nu, ny = (y1 - y0), -(u1 - u0)
        if PROF_CCW(prof) < 0:
            nu, ny = -nu, -ny
        nn = (u[0] * nu, ny, u[1] * nu)
        bld.poly([(p0[0], y0, p0[1]), (p1[0], y1, p1[1]), (p1[0] - n[0] * dep, y1, p1[1] - n[1] * dep),
                  (p0[0] - n[0] * dep, y0, p0[1] - n[1] * dep)], GRANITE, nn)
    ms.append(bld.mesh())
    parts["stone"].append(merge(ms))
    C = np.array([pa + u * x - n * 0.45 for x in np.arange(0.3, span, MER_PITCH)])
    T = np.tile(u, (len(C), 1))
    parts["merlon"].append(merlons(C, T, np.full(len(C), ytop - 0.1), np.full(len(C), ytop + MER_H), 0.85, GRANITE))
    return ytop


# ── The cimorro ─────────────────────────────────────────────────────────────────────────────────────────────
def cimorro(parts):
    arc = CATH[41:62][::-1]                                # apse, south end -> north end (cathedral nodes 61..41)
    o_dir = (O[1] - O[0]) / np.linalg.norm(O[1] - O[0])
    i_dir = (I[1] - I[0]) / np.linalg.norm(I[1] - I[0])
    town = -O[0] / np.linalg.norm(O[0])
    o0 = O[0] + o_dir * 1.3
    i0 = I[0] + i_dir * 1.3 + town * 3.0
    ie = I[-1] + (I[-2] - I[-1]) / np.linalg.norm(I[-2] - I[-1]) * 1.0
    iew = ie + town * 3.0
    chain = np.vstack([o0, CATH[62], arc, ie])           # the outer side, south -> north
    poly = np.vstack([chain, iew, i0])
    ctr = np.vstack([arc, CATH[62:63]]).mean(0)
    g = float(at(ctr[None], G_OUT)[0])
    bot = float(at(poly, BOT).min()) - 2.0
    t1 = g + 14.5                                          # lower terrace; parapet to g + 15.5
    t2 = g + 19.5                                          # upper drum terrace; parapet to g + 20.5
    n_out = seg_normals(chain, away=ctr)
    parts["cim"].append(strip(chain, np.full(len(chain), bot), np.full(len(chain), t1 + PARAPET), n_out, CIMORRO))
    back = np.vstack([chain[-1:], iew, i0, chain[:1]])
    parts["cim"].append(strip(back, np.full(4, bot), np.full(4, t1), seg_normals(back, away=ctr), CIMORRO, smooth_deg=1))
    parts["walk"].append(flat_cap(poly, t1, CIMORRO * 0.92))
    cin = offset_open(chain, -n_out, PAR_T)
    parts["cim"].append(strip(cin, np.full(len(cin), t1), np.full(len(cin), t1 + PARAPET), -n_out, CIMORRO))
    parts["cim"].append(ribbon(chain, cin, np.full(len(cin), t1 + PARAPET), np.full(len(cin), t1 + PARAPET), CIMORRO))
    C, T = place_along((chain + cin) / 2, np.ones(len(chain) - 1, bool), pitch=1.7)
    parts["merlon"].append(merlons(C, T, np.full(len(C), t1 + PARAPET - 0.12), np.full(len(C), t1 + PARAPET + MER_H), PAR_T + 0.06, CIMORRO))
    # machicolation of the lower parapet: a projecting band on corbels
    for (y0, y1, dd) in ((g + 11.4, g + 12.6, 0.85), (t1 - 0.2, t1 + 0.2, 0.3)):
        band = offset_open(arc, seg_normals(arc, away=ctr), dd)
        parts["cim"].append(strip(band, np.full(len(band), y0), np.full(len(band), y1), seg_normals(band, away=ctr), CIMORRO * 0.95))
        parts["cim"].append(ribbon(arc, band, np.full(len(band), y1), np.full(len(band), y1), CIMORRO))
        under = ribbon(arc, band, np.full(len(band), y0), np.full(len(band), y0), CIMORRO * 0.6)
        under.f = under.f[:, ::-1]
        parts["cim"].append(under)
    # corbels under the machicolation
    C, T = place_along(offset_open(arc, seg_normals(arc, away=ctr), 0.4), np.ones(len(arc) - 1, bool), pitch=1.7)
    parts["cim"].append(merlons(C, T, np.full(len(C), g + 11.45), np.full(len(C), g + 10.3), 0.8, CIMORRO * 0.9,
                                w=0.55, cap=0.0))                  # built upside down: the closed end is below
    # upper drum, 3.2 m inside the apse
    na = seg_normals(arc, away=ctr)
    up = offset_open(arc, -na, 3.2)
    upoly = up
    parts["cim"].append(strip(up, np.full(len(up), t1 - 0.3), np.full(len(up), t2 + PARAPET), na, CIMORRO))
    chord = np.vstack([up[-1:], up[:1]])
    parts["cim"].append(strip(chord, np.full(2, t1 - 0.3), np.full(2, t2), seg_normals(chord, away=up.mean(0)), CIMORRO, smooth_deg=1))
    parts["walk"].append(flat_cap(upoly, t2, CIMORRO * 0.85))
    uin = offset_open(up, -na, PAR_T)
    parts["cim"].append(strip(uin, np.full(len(uin), t2), np.full(len(uin), t2 + PARAPET), -na, CIMORRO))
    parts["cim"].append(ribbon(up, uin, np.full(len(up), t2 + PARAPET), np.full(len(up), t2 + PARAPET), CIMORRO))
    C, T = place_along((up + uin) / 2, np.ones(len(up) - 1, bool), pitch=1.7)
    parts["merlon"].append(merlons(C, T, np.full(len(C), t2 + PARAPET - 0.12), np.full(len(C), t2 + PARAPET + MER_H), PAR_T + 0.06, CIMORRO))
    band = offset_open(up, na, 0.55)
    y0, y1 = t2 - 1.2, t2 - 0.2
    parts["cim"].append(strip(band, np.full(len(band), y0), np.full(len(band), y1), na, CIMORRO * 0.95))
    parts["cim"].append(ribbon(up, band, np.full(len(band), y1), np.full(len(band), y1), CIMORRO))
    under = ribbon(up, band, np.full(len(band), y0), np.full(len(band), y0), CIMORRO * 0.6)
    under.f = under.f[:, ::-1]
    parts["cim"].append(under)
    return poly, chain


# ── Footprint: the ring of the wall (outer outline + slit + town side), even-odd keyhole ───────────────────
def simplify(P, tol):
    P = np.asarray(P, float)
    if len(P) < 3:
        return P
    a, b = P[0], P[-1]
    ab = b - a
    ln = np.linalg.norm(ab)
    d = np.abs(ab[0] * (P - a)[:, 1] - ab[1] * (P - a)[:, 0]) / ln if ln > 1e-9 else np.linalg.norm(P - a, axis=1)
    k = int(d.argmax())
    if d[k] > tol:
        return np.vstack([simplify(P[:k + 1], tol)[:-1], simplify(P[k:], tol)])
    return np.vstack([a, b])


def footprint(cim_chain, cim_poly):
    outer = np.vstack([O, cim_chain[::-1][1:-1]])          # around the outside, then back over the apse
    inner = np.vstack([I, cim_poly[-2:][::1]])              # town side, then the back of the cimorro
    outer = simplify(np.vstack([outer, outer[:1]]), 0.3)[:-1]
    inner = simplify(np.vstack([inner, inner[:1]]), 0.3)[:-1]
    o = offset([tuple(p) for p in outer], 1.5)              # CCW, grown by 1.5 m
    i = offset([tuple(p) for p in inner], -1.5)[::-1]       # clockwise, shrunk by 1.5 m (into the town)
    k = min(range(len(o)), key=lambda j: math.dist(o[j], i[0]))
    ring = o[k:] + o[:k + 1] + [i[0]] + i[1:] + [i[0]]
    return [[round(x, 2), round(z, 2)] for x, z in ring]


def inside_evenodd(x, z, R):
    c = False
    n = len(R)
    for k in range(n):
        (x0, z0), (x1, z1) = R[k], R[(k + 1) % n]
        if (z0 > z) != (z1 > z) and x < x0 + (z - z0) * (x1 - x0) / (z1 - z0):
            c = not c
    return c


# ── Colour and assembly ─────────────────────────────────────────────────────────────────────────────────────
def weather(m, amp=0.09, seed=3):
    if not len(m.v):
        return m
    k = 1 + amp * (2 * fbm(m.v, (0.06, 0.15, 0.06), seed, 3) - 1)
    m.c = np.clip(m.c * k[:, None], 0, 1)
    return m


def main():
    out = ROOT / "models" / "Q3050235"
    out.mkdir(parents=True, exist_ok=True)
    parts = {"stone": [], "walk": [], "merlon": [], "dark": [], "cim": []}
    towers = find_towers()
    built = []
    for t in towers:
        extra = 7.6 if t["gate"] else None
        built.append(tower(t, parts, extra))
    for name in GREAT:
        pair = [b for t, b in zip(towers, built) if t["gate"] == name]
        great_gate(name, pair[0], pair[1], parts)
    Or, Oin, Ir = wall(towers, parts)
    gates(towers, parts)
    cpoly, cchain = cimorro(parts)
    meshes = {k: weather(merge(v), seed=i + 1) for i, (k, v) in enumerate(parts.items())}
    meshes["dark"] = merge(parts["dark"])
    stone = merge([meshes["stone"], meshes["walk"], meshes["merlon"], meshes["cim"], meshes["dark"]])
    tris, size = write_glb(out / "model.glb", [("murallas_de_avila", stone)], roughness=0.92)
    lo, hi = stone.v.min(0), stone.v.max(0)
    print(f"towers: {len(towers)}, merlons: {meshes['merlon'].tris // 12}")
    print(f"model.glb: {tris:,} triangles, {size / 2**20:.2f} MB, extent x {lo[0]:.2f}..{hi[0]:.2f}, "
          f"y {lo[1]:.2f}..{hi[1]:.2f}, z {lo[2]:.2f}..{hi[2]:.2f}")
    fp = footprint(cchain, cpoly)
    tests = {"town centre": (0, 0), "inside, 8 m from the wall": tuple(Ir[200] * (1 - 8 / np.linalg.norm(Ir[200]))),
             "on the wall": tuple((Ir[200] + Or[np.argmin(np.linalg.norm(Or - Ir[200], axis=1))]) / 2),
             "on a tower": tuple(built[40]["ctr"]), "on the cimorro": tuple(cpoly.mean(0)), "500 m outside": (0, 800)}
    for nm, (x, z) in tests.items():
        print(f"footprint test {nm}: {'IN' if inside_evenodd(x, z, fp) else 'out'}")
    meta = out / "meta.json"
    if meta.exists():                                     # keep the footprint of meta.json in step with the plan
        mj = json.loads(meta.read_text(encoding="utf-8"))
        mj["footprint"] = fp
        mj["triangles"] = tris
        meta.write_text(json.dumps(mj, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        print(f"meta.json: footprint {len(fp)} points, triangles {tris}")
    else:
        (out / "footprint.tmp.json").write_text(json.dumps(fp), encoding="utf-8")


if __name__ == "__main__":
    main()
